/** 按参考笔记构造的小词库，故意混入不一致的词根写法、干扰词和屈折形式 */
type M = { form: string; meaning: string }
let n = 0
function W(word: string, zh: string, pos: string, o: any = {}): any {
  const m: any = {}
  if (o.p) m.prefix = o.p as M
  if (o.r) m.root = o.r as M
  if (o.s) m.suffix = o.s as M
  return {
    id: 'w' + n++, word, phonetic: '', level: o.level || 'CET6', createdAt: '', updatedAt: '',
    meanings: [{ chinese: zh, partOfSpeech: pos }],
    morphemes: Object.keys(m).length ? m : undefined,
    synonyms: (o.syn || []).map((x: string) => ({ word: x })),
    antonyms: (o.ant || []).map((x: string) => ({ word: x })),
    word_family: o.fam, topics: o.topics, morphology: o.morph,
    common_phrases: (o.ph || []).map((x: string) => ({ phrase_en: x.split('|')[0], phrase_zh: x.split('|')[1] || '' }))
  }
}
